        bad_items = BadItems()
        # We need to trigger an exception so that rich traceback is called.
        # And we need bad_items to be in the locals of the frame where the exception occurs.
        raise RuntimeError("Trigger")

    trigger_error()
except Exception:
    sys.excepthook(*sys.exc_info())

